Lemma reserve_mspec N s n : okN N s -> (n <= N)%nat ->
  mspec (reserve s n)
    (fun s' => okN N s' /\ s_words s' = s_words s /\ s_neg s' = s_neg s /\ (n <= capacity s')%nat /\ (capacity s <= capacity s')%nat)
    1 (BB N).
