Lemma norm_count_spec : forall f y x, wordZ y -> y <> 0 -> 2^63 <= y * 2 ^ (Z.of_nat f) -> 0 <= x ->
  let x' := norm_count f y x in x <= x' <= x + Z.of_nat f /\ 2^63 <= y * 2 ^ (x' - x) < 2^64.
Proof.
