  Lemma shl_decomp a : wordZ a ->
    W.shl a k = (a mod 2 ^ k1) * 2 ^ k /\ a * 2 ^ k = W.shl a k + W.M * (a / 2 ^ k1) /\ 0 <= a / 2 ^ k1 < 2 ^ k.
Proof.
