Lemma shr_bits_mspec N s k : okN N s -> 0 < k < 64 ->
  mspec (shr_bits s k)
    (fun s' => okN N s' /\ reduced s' /\ (size s' <= size s)%nat /\ (capacity s <= capacity s')%nat) 1 (BB N).
Proof.
