(* [comment removed for export] *)
Lemma two_word_sub_exact A B sh sl : wordZ A -> wordZ B -> wordZ sl -> 0 <= sh ->
  sh * W.M + sl <= A * W.M + B ->
  let x := W.sub B sl in
  let bo := W.b2z (W.ltu B x) in
  W.sub A (W.wrap (sh + bo)) * W.M + x = (A * W.M + B) - (sh * W.M + sl).
Proof.
