  Lemma ddq1_body_exact A B q : wordZ A -> wordZ B -> d * H <= A * W.M + B ->
    let '(A', B', q') := ddq1_body A B q dHi dLo1 in
    A' * W.M + B' = A * W.M + B - d * H /\ wordZ A' /\ wordZ B' /\ q' = W.add q 1.
Proof.
