Lemma divloop_shape f : forall k l d dws rws qws, words_ok rws -> words_ok qws ->
  let (r1, q1) := divloop f k l d dws rws qws in
  length r1 = length rws /\ length q1 = length qws /\ words_ok r1 /\ words_ok q1.
