(* [comment removed for export] *)
Lemma nwords_after_growth v k t w :
  (1 <= k)%nat -> 0 <= v < 10 * W.M ^ Z.of_nat (k - 1) -> 0 <= t <= 18 ->
  0 <= w < 10 ^ t * (v + 1) -> (nwords w <= k)%nat.
